class LRUCache<K, V> {
  private map = new Map<K, V>();

  constructor(private capacity: number) {}

  get(key: K): V | undefined {
    if (!this.map.has(key)) return undefined;
    const value = this.map.get(key) as V;
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  put(key: K, value: V): void {
    if (this.map.has(key)) this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.capacity) {
      const oldest = this.map.keys().next().value as K;
      this.map.delete(oldest);
    }
  }
}

type Op = ["get", string] | ["put", string, number];

function runLRU(capacity: number, ops: Op[]): Array<number | null> {
  const cache = new LRUCache<string, number>(capacity);
  const out: Array<number | null> = [];
  for (const op of ops) {
    if (op[0] === "put") cache.put(op[1], op[2]);
    else out.push(cache.get(op[1]) ?? null);
  }
  return out;
}

